# CMH-ish one-sided p values from conditional city-type purchase totals; report BH thresholds
import pandas as pd,numpy as np,glob
from scipy.stats import norm
from statsmodels.stats.multitest import multipletests
U=pd.read_csv('user_001.csv');L=pd.concat([pd.read_csv(f,usecols=['listing_id','category_id']) for f in glob.glob('listing_*.csv')]);P=pd.read_csv('purchase_001.csv').merge(U[['user_id','city','user_type']],left_on='buyer_id',right_on='user_id').merge(L,on='listing_id');K=pd.read_csv('category_001.csv').set_index('category_id').category_name;main=U.groupby('city').size().loc[lambda s:s>1].index;X=P[P.city.isin(main)]
ct=X.groupby(['city','user_type']).size();tc=X.groupby(['user_type','category_id']).size();tt=X.groupby('user_type').size();o=X.groupby(['city','user_type','category_id']).size()
rows=[]
for city in main:
 for cat in range(9,73):
  ob=ex=var=0
  for t in tt.index:
   n=ct.get((city,t),0); N=tt[t]; Kc=tc.get((t,cat),0); ob+=o.get((city,t,cat),0); ex+=n*Kc/N
   # hypergeometric variance for city vs rest conditional margins
   var+=n*(Kc/N)*(1-Kc/N)*((N-n)/(N-1))
  z=(ob-ex)/np.sqrt(var);rows.append((city,cat,ob,ex,z,norm.cdf(z)))
R=pd.DataFrame(rows,columns=['city','cat','obs','exp','z','p']);R['category']=R.cat.map(K)
for alpha in [.2,.1,.05,.01]:
 rej,q,_,_=multipletests(R.p,alpha=alpha,method='fdr_bh');Q=R[rej].copy();print('\nFDR',alpha,'n',len(Q));print(Q.sort_values('p')[['city','category','obs','exp','z','p']].to_string(index=False,formatters={c:'{:.4g}'.format for c in ['exp','z','p']}))
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:30000});
text(r.output);

