for city in main:
 for cat in range(9,73):
  ob=ex=v=0
  for t in tt.index:
   n=ct.get((city,t),0);p=tc.get((t,cat),0)/tt[t];ob+=o.get((city,t,cat),0);ex+=n*p;v+=n*p*(1-p)
