import pandas as pd,numpy as np,glob
U=pd.read_csv('user_001.csv'); L=pd.concat([pd.read_csv(f,usecols=['listing_id','category_id']) for f in glob.glob('listing_*.csv')]); P=pd.read_csv('purchase_001.csv').merge(U[['user_id','city','user_type']],left_on='buyer_id',right_on='user_id').merge(L,on='listing_id'); P['month']=pd.to_datetime(P.purchase_time).dt.month
K=pd.read_csv('category_001.csv').set_index('category_id').category_name
T={'Barcelona':['Art','Books','Decor'],'Bilbao':['Bags','Formalwear',"Women's Shoes"],'Madrid':['Fitness','Garden','Pets'],'Sevilla':['Computers','Music','Video Games'],'Valencia':['Bicycles','Furniture','Tools'],'Zaragoza':['Cameras','Collectibles','Musical Instruments']}
name_to_id={v:k for k,v in K.items()}; main=U.groupby('city').size().loc[lambda s:s>1].index; X=P[P.city.isin(main)]
# Leave city out: within each user type, preserve target city's total purchases and use category shares in other cities.
rows=[]
for city,names in T.items():
 for name in names:
  cat=name_to_id[name]; obs=exp=0
  for typ in X.user_type.unique():
   here=X[(X.city==city)&(X.user_type==typ)]; rest=X[(X.city!=city)&(X.user_type==typ)]; obs+=(here.category_id==cat).sum(); exp+=len(here)*(rest.category_id==cat).mean()
  # month directions versus other cities, additionally stratifying type
  below=0
  for m in range(1,7):
   om=em=0
   for typ in X.user_type.unique():
    here=X[(X.city==city)&(X.user_type==typ)&(X.month==m)];rest=X[(X.city!=city)&(X.user_type==typ)&(X.month==m)];om+=(here.category_id==cat).sum();em+=len(here)*(rest.category_id==cat).mean()
   below += om < em
  rows.append((city,name,obs,exp,obs/exp,below))
print(pd.DataFrame(rows,columns=['city','category','purchases','loo_expected','ratio','months_below_expected']).to_string(index=False,formatters={'loo_expected':'{:.1f}'.format,'ratio':'{:.2f}'.format}))
